using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static partial class HedgeDetailUpdater {
static Mesh RoundedHedge(Mesh source,Quaternion rotation){var d=Read(source);var p=F<Vector3[]>(d,"p");var normals=F<Vector3[]>(d,"normal");var uv=F<Vector2[][]>(d,"uv")[0];var ids=F<int[]>(d,"ids");var pp=new List<Vector3>();var nn=new List<Vector3>();var tt=new List<Vector2>();var ii=new List<int>();var leaf=new List<Vector3>();for(int k=0;k<ids.Length;k+=3){var ix=new[]{ids[k],ids[k+1],ids[k+2]};bool foliage=ix.All(j=>uv[j].y>.265f&&uv[j].y<.335f&&uv[j].x<.351f);if(foliage){leaf.AddRange(ix.Select(j=>rotation*p[j]));continue;}foreach(int j in ix){ii.Add(pp.Count);pp.Add(p[j]);nn.Add(normals[j]);tt.Add(uv[j]);}}
var lo=new Vector3(leaf.Min(v=>v.x),leaf.Min(v=>v.y),leaf.Min(v=>v.z));var hi=new Vector3(leaf.Max(v=>v.x),leaf.Max(v=>v.y),leaf.Max(v=>v.z));var center=(lo+hi)*.5f;var half=(hi-lo)*.5f;float radius=Mathf.Min(half.x,half.y,half.z)*.9f;var inner=half-Vector3.one*radius;var inv=Quaternion.Inverse(rotation);
Func<Vector3,Vector3> shape=(v)=>{var rel=v-center;var core=new Vector3(Mathf.Clamp(rel.x,-inner.x,inner.x),Mathf.Clamp(rel.y,-inner.y,inner.y),Mathf.Clamp(rel.z,-inner.z,inner.z));var normal=(rel-core).normalized;float noise=Mathf.PerlinNoise(v.x*5.7f+v.z*2.1f,v.y*7.2f+v.z*4.3f);return center+core+normal*(radius-.045f+Mathf.PerlinNoise(v.x*2.7f+v.z*1.3f,v.y*3.2f+v.z*2.1f)*.075f+noise*.018f);};
Action<Vector3,Vector3,Vector3,int,int> face=(origin,u,v,nu,nv)=>{for(int a=0;a<nu;a++)for(int b=0;b<nv;b++){var corners=new[]{origin+u*(a/(float)nu)+v*(b/(float)nv),origin+u*((a+1f)/nu)+v*(b/(float)nv),origin+u*((a+1f)/nu)+v*((b+1f)/nv),origin+u*(a/(float)nu)+v*((b+1f)/nv)};int start=pp.Count;for(int k=0;k<4;k++){var point=shape(corners[k]);var rel=corners[k]-center;var core=new Vector3(Mathf.Clamp(rel.x,-inner.x,inner.x),Mathf.Clamp(rel.y,-inner.y,inner.y),Mathf.Clamp(rel.z,-inner.z,inner.z));pp.Add(inv*point);var normal=(rel-core).normalized;var grain=new Vector3(Mathf.PerlinNoise(point.y*12.3f,point.z*9.1f)-.5f,Mathf.PerlinNoise(point.z*11.7f,point.x*10.1f)-.5f,Mathf.PerlinNoise(point.x*9.3f,point.y*13.1f)-.5f);nn.Add(inv*(normal+Vector3.ProjectOnPlane(grain,normal)*.32f).normalized);float sx=(k==1||k==2)?1:0;float sy=k>=2?1:0;if((a&1)==1)sx=1-sx;if((b&1)==1)sy=1-sy;float seed=Mathf.Sin((origin.x+origin.y*3.1f+origin.z*7.7f+a*23.17f+b*47.77f)*12.9898f)*43758.5453f;float ru=seed-Mathf.Floor(seed);float rv=Mathf.Repeat(ru*17.319f,.99f);tt.Add(new Vector2(.035f+sx*.023f,.292f+sy*.012f));}var mid=(corners[0]+corners[2])*.5f;pp.Add(inv*shape(mid));nn.Add((nn[start]+nn[start+1]+nn[start+2]+nn[start+3]).normalized);float jitter=Mathf.PerlinNoise(mid.x*8.73f+mid.y*2.3f,mid.z*9.17f);tt.Add(new Vector2(.0465f+(jitter-.5f)*.0015f,.298f+(Mathf.Repeat(jitter*7.17f,1)-.5f)*.001f));ii.AddRange(new[]{start,start+1,start+4,start+1,start+2,start+4,start+2,start+3,start+4,start+3,start,start+4});// A small cupped leaf adds a real silhouette accent without cards or alpha overdraw.
if(Vector3.Dot((nn[start]+nn[start+1]+nn[start+2]+nn[start+3]).normalized,inv*Vector3.down)<.8f){var normalLocal=nn[start+4];float seedLeaf=Mathf.Repeat(Mathf.Sin(mid.x*43.13f+mid.y*73.77f+mid.z*19.17f)*45758.5453f,1);var tangent=Vector3.Cross(normalLocal,Mathf.Abs(normalLocal.y)<.85f?Vector3.up:Vector3.right).normalized;var bitangent=Vector3.Cross(normalLocal,tangent).normalized;float angle=seedLeaf*Mathf.PI*2;var dir=tangent*Mathf.Cos(angle)+bitangent*Mathf.Sin(angle);var across=Vector3.Cross(normalLocal,dir).normalized;var anchor=inv*shape(mid)+normalLocal*.01f;float length=.048f+seedLeaf*.025f,width=length*.48f;int l=pp.Count;var lp=new[]{anchor-dir*length*.5f,anchor-across*width*.5f,anchor+dir*length*.5f,anchor+across*width*.5f,anchor+normalLocal*.012f};for(int z=0;z<5;z++){pp.Add(lp[z]);nn.Add((normalLocal+(lp[z]-anchor)*4).normalized);tt.Add(new Vector2(.044f+(z==2?.001f:0),.297f+(z==3?.001f:0)));}ii.AddRange(new[]{l,l+1,l+4,l+1,l+2,l+4,l+2,l+3,l+4,l+3,l,l+4});}}};
var size=hi-lo;int nx=Mathf.CeilToInt(size.x/.35f),ny=Mathf.CeilToInt(size.y/.18f),nz=Mathf.CeilToInt(size.z/.35f);
face(new Vector3(lo.x,lo.y,hi.z),Vector3.right*size.x,Vector3.up*size.y,nx,ny);face(new Vector3(hi.x,lo.y,lo.z),Vector3.left*size.x,Vector3.up*size.y,nx,ny);face(new Vector3(hi.x,lo.y,hi.z),Vector3.back*size.z,Vector3.up*size.y,nz,ny);face(new Vector3(lo.x,lo.y,lo.z),Vector3.forward*size.z,Vector3.up*size.y,nz,ny);face(new Vector3(lo.x,hi.y,hi.z),Vector3.right*size.x,Vector3.back*size.z,nx,nz);face(new Vector3(lo.x,lo.y,lo.z),Vector3.right*size.x,Vector3.forward*size.z,nx,nz);
var m=new Mesh{name=source.name+" Detailed"};m.SetVertices(pp);m.SetNormals(nn);m.SetUVs(0,tt);m.SetTriangles(ii,0);m.RecalculateBounds();m.RecalculateTangents();return m;}
static void Repair(){var sc=SceneManager.GetActiveScene();if(sc.path!="Assets/Scenes/Oasis/MobileOptimization/Gangstar City.unity")throw new Exception("Wrong scene");string log="";foreach(string name in new[]{"green","green1"}){var src=AssetDatabase.LoadAllAssetsAtPath("Assets/Scenes/Oasis/3D/Fbx/Petrol pump.fbx").OfType<Mesh>().Single(m=>m.name==name);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/"+name+".prefab");var updated=RoundedHedge(src,prefab.transform.localRotation);var target=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/HedgeDetail/"+name+" Detailed.asset");target.Clear();target.indexFormat=updated.indexFormat;target.vertices=updated.vertices;target.normals=updated.normals;target.uv=updated.uv;target.triangles=updated.triangles;target.tangents=updated.tangents;target.RecalculateBounds();target.UploadMeshData(false);EditorUtility.SetDirty(target);UnityEngine.Object.DestroyImmediate(updated);log+=name+"="+target.triangles.Length/3+" triangles\n";}var importer=(TextureImporter)AssetImporter.GetAtPath("Assets/Scenes/Oasis/3D/Texture/petrol atlas.png");importer.anisoLevel=4;importer.mipMapBias=-.3f;importer.textureCompression=TextureImporterCompression.CompressedHQ;importer.compressionQuality=100;importer.SaveAndReimport();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/HedgeRepair.txt","SUCCESS continuous rounded mesh, consistent per-cell foliage UV, no folded UV interpolation. Same textures/materials, original distant LODs and curbs retained.\n"+log);CaptureHedge();}
}





